if type(ui) ~= "table" or type(events) ~= "table" or type(utils) ~= "table" then error("envy: Neverlose environment required", 0) end
local unpack_values = unpack or table.unpack
local get_environment = getfenv
local set_environment = setfenv
local functions, callbacks = {}, {}
local function pack(...) return {count = select("#", ...), ...} end
local function bind_environment(callback, environment)
    if set_environment then set_environment(callback, environment) end
    return callback
end
local function create_function(implementation, upvalues, environment)
    local callback = function(...) return implementation(upvalues, get_environment and get_environment(1) or environment, ...) end
    return bind_environment(callback, environment)
end

callbacks["root.4.1"] = function(upvalues, environment)
    return bind_environment(function(r, E, ...)
        local V, P = xpcall(E.fn, upvalues[1][1].traceback, ...)
        if V then
            E.errors = 0
            return P
        end
        E.errors = E.errors + 1
        if E.errors >= upvalues[2][1] then
            E.disabled = true
            upvalues[1][1].error(E.owner .. ("@" .. r.name), P)
        end
    end, environment)
end

callbacks["root.4.2"] = function(upvalues, environment)
    return bind_environment(function(r, ...)
        if not upvalues[1][1].alive or r.running then
            return 
        end
        r.running = r.guarded
        local E = r.handlers
        local V = upvalues[1][1].sampler
        for P = 1, #E, 1 do
            local b = E[P]
            if not b.disabled then
                local E
                if V then
                    E = V(upvalues[2][1], r, b, ...)
                else
                    E = upvalues[2][1](r, b, ...)
                end
                if E ~= nil then
                    r.running = false
                    return E
                end
            end
        end
        r.running = false
    end, environment)
end

