callbacks["root.11.23"] = function(upvalues, environment)
    return bind_environment(function(r, E)
        local V = upvalues[1][1]:config()
        if r then
            if type(V.saved_configs[E]) ~= "table" then
                return false, "not found"
            end
            V.autosave = {
                enabled = true,
                name = E,
            }
            upvalues[2][1].snapshot = json.stringify(V.saved_configs[E])
        else
            V.autosave = {
                enabled = false,
            }
            upvalues[2][1].snapshot = nil
        end
        upvalues[2][1].dirty = false
        upvalues[1][1]:save_config()
        return true, E
    end, environment)
end

callbacks["root.11.29"] = function(upvalues, environment)
    return bind_environment(function(r)
        local E = upvalues[1][1]()
        if not upvalues[2][1].loaded or not E.enabled or not upvalues[2][1].dirty then
            return 
        end
        if not r and globals.realtime < upvalues[2][1].next_save then
            return 
        end
        local V = upvalues[3][1]:config()
        local P = E.name
        if type(V.saved_configs[P]) ~= "table" then
            upvalues[4][1].set_autosave(false)
            return 
        end
        local b = upvalues[4][1].capture("all")
        local R = json.stringify(b)
        upvalues[2][1].dirty = false
        if R == upvalues[2][1].snapshot then
            return 
        end
        V.saved_configs[P] = b
        V.last_cfg = b
        V.last_loaded_name = P
        upvalues[3][1]:save_config()
        upvalues[2][1].snapshot = R
    end, environment)
end

callbacks["root.11.30"] = function(upvalues, environment)
    return bind_environment(function()
        if upvalues[1][1].loaded then
            return 
        end
        upvalues[1][1].frames = upvalues[1][1].frames + 1
        if upvalues[1][1].frames < upvalues[2][1] then
            return 
        end
        upvalues[1][1].loaded = true
        local r = upvalues[3][1]:config()
        local E = r.last_loaded_name
        local V = (E and r.saved_configs[E]) or r.last_cfg
        if type(V) ~= "table" then
            upvalues[4][1]("loaded", false)
            return 
        end
        local P, b = pcall(upvalues[5][1].apply, V, "all")
        if P then
            local V = upvalues[5][1].capture("all")
            if E and r.saved_configs[E] then
                r.saved_configs[E] = V
            end
            r.last_cfg = V
            upvalues[3][1]:save_config()
            upvalues[6][1](E, V)
            upvalues[4][1]("loaded", true)
            return 
        end
        upvalues[7][1].error("config.autoload", b)
        if r.autosave.name == E then
            r.autosave = {
                enabled = false,
            }
        end
        r.last_loaded_name, r.last_cfg = nil, nil
        upvalues[3][1]:save_config()
        upvalues[4][1]("loaded", false)
    end, environment)
end

