callbacks["root.14.3"] = function(upvalues, environment)
    return bind_environment(function(r, E, V)
        local P = upvalues[1][1].layout
        if not P then
            P = {
                panel_min = vector(),
                panel_max = vector(),
                items = {
                },
            }
            upvalues[1][1].layout = P
        end
        if P.menu_x == r.x and (P.menu_y == r.y and (P.menu_w == E.x and (P.menu_h == E.y and P.scale == V))) then
            return P
        end
        P.menu_x, P.menu_y, P.menu_w, P.menu_h = r.x, r.y, E.x, E.y
        P.scale = V
        local b = r.x + E.x
        local R = math.min(E.x, upvalues[2][1] * V)
        local L = b - R * 0.5
        local w = math.min(upvalues[3][1] * V, R - 24 * V)
        local h = upvalues[4][1] * V
        local v = L - w * 0.5
        local i = r.y + E.y
        local z, S = i - 16 * V, i + h
        P.base_top, P.base_bottom = z, S
        P.panel_min:init(v, z, 0)
        P.panel_max:init(v + w, S, 0)
        local U = w / #upvalues[1][1].icons
        for r = 1, #upvalues[1][1].icons, 1 do
            local E = v + (r - 1) * U
            local b = E + U
            local R = P.items[r]
            if not R then
                R = {
                    item_min = vector(),
                    item_max = vector(),
                    indicator_min = vector(),
                    indicator_max = vector(),
                    icon_center = vector(),
                }
                P.items[r] = R
            end
            R.slot_left, R.slot_right = E, b
            R.base_item_min = i + 7 * V
            R.base_item_max = S - 8 * V
            R.base_indicator_min = S - 4 * V
            R.base_indicator_max = S - 2 * V
            R.base_icon = ((R.base_item_min + R.base_item_max) - upvalues[1][1].sizes[r].y) * 0.5
            R.item_min:init(E + 8 * V, R.base_item_min, 0)
            R.item_max:init(b - 8 * V, R.base_item_max, 0)
            R.indicator_min:init(E + 22 * V, R.base_indicator_min, 0)
            R.indicator_max:init(b - 22 * V, R.base_indicator_max, 0)
            R.icon_center:init((E + b) * 0.5, R.base_icon, 0)
        end
        return P
    end, environment)
end

callbacks["root.14.4"] = function(upvalues, environment)
    return bind_environment(function(r)
        local E = upvalues[1][1].tree.tab
        local V = upvalues[2][1].clamp(ui.get_alpha(), 0, 1)
        if not E or V <= 0 then
            upvalues[3][1].mouse_down = common.is_button_down(1)
            upvalues[3][1].block_input = false
            return 
        end
        if not upvalues[3][1].icons then
            upvalues[3][1].icons = {
            }
            for r = 1, #upvalues[4][1], 1 do
                upvalues[3][1].icons[r] = ui.get_icon(upvalues[4][1][r])
            end
        end
        local P = math.max(0.75, render.get_scale(1) or 1)
        if upvalues[3][1].scale ~= P then
            upvalues[3][1].scale = P
            local r = math.max(16, math.floor(18 * P + 0.5))
            if upvalues[3][1].font then
                upvalues[3][1].font:set_size(r)
            else
                upvalues[3][1].font = render.load_font("Consolas Bold", r, "ab")
            end
            for r = 1, #upvalues[3][1].icons, 1 do
                upvalues[3][1].sizes[r] = render.measure_text(upvalues[3][1].font, nil, upvalues[3][1].icons[r])
            end
            upvalues[3][1].layout = nil
        end
        local b = upvalues[5][1](upvalues[6][1].menu_position or ui.get_position(), upvalues[6][1].menu_size or ui.get_size(), P)
        local R = (V * V) * (3 - 2 * V)
        local L = (-upvalues[7][1] * P) * (1 - R)
        b.panel_min.y = b.base_top + L
        b.panel_max.y = b.base_bottom + L
        local w, h, v = r.accent, r.text, r.preview_text
        local i, z, S = r.main_background, r.shadows, r.selection
        local U = upvalues[3][1].colors
        render.shadow(b.panel_min, b.panel_max, U.shadow:init(z.r, z.g, z.b, math.floor((z.a or 255) * V + 0.5)), 18 * P, 0, 16 * P)
        render.rect(b.panel_min, b.panel_max, U.background:init(i.r, i.g, i.b, math.floor(255 * V + 0.5)), 16 * P)
        local I = ui.get_mouse_position()
        local n = tonumber(E:get()) or 1
        local C
        for r = 1, #upvalues[3][1].icons, 1 do
            local E = b.items[r]
            E.item_min.y = E.base_item_min + L
            E.item_max.y = E.base_item_max + L
            E.indicator_min.y = E.base_indicator_min + L
            E.indicator_max.y = E.base_indicator_max + L
            E.icon_center.y = E.base_icon + L
            local R = I.x >= E.slot_left and (I.x <= E.slot_right and (I.y >= E.item_min.y and I.y <= E.item_max.y))
            if R then
                C = r
            end
            local i = n == r
            local z
            if i then
                render.rect(E.indicator_min, E.indicator_max, U.indicator:init(w.r, w.g, w.b, math.floor(230 * V + 0.5)), 2 * P)
                z = U.icon:init(w.r, w.g, w.b, math.floor(255 * V + 0.5))
            elseif R then
                render.rect(E.item_min, E.item_max, U.hover:init(S.r, S.g, S.b, math.floor((S.a or 255) * V + 0.5)), 7 * P)
                z = U.icon:init(h.r, h.g, h.b, math.floor(235 * V + 0.5))
            else
                z = U.icon:init(v.r, v.g, v.b, math.floor(210 * V + 0.5))
            end
            render.text(upvalues[3][1].font, E.icon_center, z, "c", upvalues[3][1].icons[r])
        end
        local t = common.is_button_down(1)
        if t and (not upvalues[3][1].mouse_down and C) then
            upvalues[3][1].block_input = true
            local r = n == C and upvalues[8][1].get(C)
            if r and (r.search and r.search:get() ~= "") then
                r.open(math.max(1, r.active_index:get()))
            end
            E:set(C)
            upvalues[9][1].play("ui/panorama/submenu_scroll_01.wav")
        elseif not t then
            upvalues[3][1].block_input = false
        end
        upvalues[3][1].mouse_down = t
    end, environment)
end

