callbacks["root.14.7"] = function(upvalues, environment)
    return bind_environment(function(r, E, V)
        local P = upvalues[1][1].tree.home.section
        if not P then
            return 
        end
        local b = P:get()
        local R, L, w = r:to_hex(), E:to_hex(), V:to_hex()
        local h = upvalues[2][1]
        if h.selected == b and (h.accent == R and (h.text == L and h.preview == w)) then
            return 
        end
        h.selected, h.accent, h.text, h.preview = b, R, L, w
        local v = {
        }
        for r = 1, #upvalues[3][1], 1 do
            local E, V = ui.get_icon(upvalues[3][1][r][1]), upvalues[3][1][r][2]
            if b == r then
                v[r] = "\007" .. (R .. (E .. ("  \007" .. (L .. V))))
            else
                v[r] = "\007" .. (w .. (E .. ("  " .. V)))
            end
        end
        P:update(v)
    end, environment)
end

callbacks["root.14.9"] = function(upvalues, environment)
