        upvalues[2][1].last_name_update = E
        upvalues[1][1] = E + upvalues[3][1]
        upvalues[4][1]:init(math.floor(r.r * 0.5), math.floor(r.g * 0.5), math.floor(r.b * 0.5), r.a)
        for E = 1, #upvalues[5][1], 1 do
            local P = upvalues[5][1][E]
            local b, R = P.dim or upvalues[4][1], P.bright or r
            if P.anim then
                P.anim:set_colors(b, R)
            else
