callbacks["root.15.1"] = function(upvalues, environment)
    return bind_environment(function(r)
        local E, V, P
        for b = 1, #upvalues[1][1], 1 do
            local R = upvalues[1][1][b]
            local L = (render.measure_text(1, "s", R)).x
            if L > 0 then
                local Z = math.abs(L - r)
