callbacks["root.15.2"] = function(upvalues, environment)
    return bind_environment(function(r, E, V, P)
        local b = math.max(render.get_scale(1) or 1, 0.5)
        local R = upvalues[1][1].menu_size or ui.get_size()
        local L = math.min(R.x, upvalues[2][1] * b)
        local w = math.max(180 * b, (L - 36 * b) * 0.5)
        local h = w - 28 * b
        local v = V == "half"
        local i = v and (h - 8 * b) * 0.5 or h
        local z = math.max(48 * b, i * (v and 1.12 or 1.2) - 10 * b)
        local S, U = upvalues[3][1](b)
        local I = r .. (" " .. E)
        local n = (render.measure_text(1, "s", I)).x
        local C = math.max(0, math.floor((z - n) / math.max(1, U * 2)) - 2)
        local t = string.rep(S, C)
        while C > 0 and (render.measure_text(1, "s", t .. (I .. t))).x > z do
            C = C - 1
            t = string.rep(S, C)
        end
        return "\00700000000" .. (t .. ((P or "\r") .. (I .. ("\00700000000" .. (t .. "\007DEFAULT")))))
    end, environment)
end

