        if not upvalues[1][1].tree.misc.eblan_esp:get() then
            return 
        end
        local E, V = r:ball()
        if not V then
            return 
        end
        local P = render.world_to_screen(upvalues[2][1]:init(E.x, E.y, E.z + 20))
        if not P then
            return 
        end
        local b = "pidor"
        render.text(upvalues[3][1], P, upvalues[4][1], "c", b)
        if V:is_visible() then
            local r = (render.measure_text(upvalues[3][1], nil, b)).x / 2 + 4
            render.text(upvalues[5][1], upvalues[6][1]:init(P.x + r, P.y, 0), upvalues[4][1], nil, "HIT")
        end
    end, environment)
end

callbacks["root.36.4"] = function(upvalues, environment)
    return bind_environment(function(r, E)
        if not upvalues[1][1].values.soccer_aim then
            return 
        end
        local P, b = r:ball()
        if not b or not b:is_visible() then
            return 
        end
        local R = entity.get_local_player()
        if not R or not R:is_alive() then
            return 
        end
        local L = R:get_eye_position()
        local w, h, v = P.x - L.x, P.y - L.y, P.z - L.z
        local i = math.sqrt((w * w + h * h) + v * v)
        if i <= 1e-06 then
            return 
        end
        E.view_angles.x = -math.deg(math.asin(v / i))
        E.view_angles.y = math.deg(math.atan2(h, w))
        E.view_angles.z = 0
    end, environment)
end

