callbacks["root.37.4"] = function(upvalues, environment)
    return bind_environment(function(r)
        local E = upvalues[1][1].tree.misc.clantag
        if not E:get() then
            r:reset_cycle()
            if r.current ~= nil and r.current ~= "" then
                r:apply("")
            end
            return 
        end
        local V = E.mode:get() == "Custom"
        local P = V and E.phase_count:get() or #upvalues[2][1]
        if P == 0 then
            r:apply(E.phase_1:get())
            return 
        end
        local b = globals.realtime
        local R = b >= r.next_phase
        if r.index == 0 or r.index > P or (r.last_time and b < r.last_time) then
            r.index, R = 1, true
        elseif R then
            r.index = r.index % P + 1
        end
        r.last_time = b
        local L, w
        if V then
            L, w = upvalues[3][1](E, r.index)
        else
            L, w = upvalues[2][1][r.index].text, upvalues[2][1][r.index].delay
        end
        if R then
            r.next_phase = b + w
        end
        r:apply(L)
    end, environment)
end

