callbacks["root.41.4"] = function(upvalues, environment)
    return bind_environment(function(Z, r, E, V, P, b)
        local R = V / 8
        if E == 3 then
            return function(E)
                local V = 0
                for P = 0, P - 1, 1 do
                    local R = (ffi.cast("const float*", ((Z + r) + E * b) + P * 4))[0]
                    if R ~= R or R == math.huge or R == -math.huge then
                        R = 0
                    end
                    V = V + R
                end
                return V / P
            end
        end
        local L = 2 ^ (V - 1)
        return function(E)
            local w = 0
            for P = 0, P - 1, 1 do
                local h = (r + E * b) + P * R
                local v
                if V == 8 then
                    v = (Z[h] - 128) / 128
                else
                    v = 0
                    for r = R - 1, 0, -1 do
                        v = v * 256 + Z[h + r]
                    end
                    if v >= L then
                        v = v - L * 2
                    end
                    v = v / L
                end
                w = w + v
            end
            return w / P
        end
    end, environment)
end

callbacks["root.41.5"] = function(upvalues, environment)
    return bind_environment(function(r)
        if r:sub(1, 4) ~= "RIFF" or r:sub(9, 12) ~= "WAVE" then
            return nil
        end
        local E = ffi.cast("const uint8_t*", r)
        local V = #r
        local P = 12
        local b, R, L, w, h, v, i
        while P + 8 <= V do
            local z = r:sub(P + 1, P + 4)
            local S = upvalues[1][1](E, P + 4)
            local U = P + 8
            if U + S > V then
                return nil
            end
            if z == "fmt " then
                if S < 16 then
                    return nil
                end
                b, R = upvalues[2][1](E, U), upvalues[2][1](E, U + 2)
                L, w, h = upvalues[1][1](E, U + 4), upvalues[2][1](E, U + 12), upvalues[2][1](E, U + 14)
            elseif z == "data" then
                v, i = U, S
            end
            P = (U + S) + S % 2
        end
        if not L or not i or i <= 0 then
            return nil
        end
        if R < 1 or R > 8 or L < 8000 or L > 192000 then
            return nil
        end
        local z = b == 1 and (h == 8 or h == 16 or h == 24 or h == 32)
        if not z and not (b == 3 and h == 32) then
            return nil
        end
        if w ~= (R * h) / 8 or i % w ~= 0 then
            return nil
        end
        local S = i / w
        local U = math.max(1, math.floor((S * upvalues[3][1]) / L))
        if U * 2 + 44 > upvalues[4][1].MAX_READ then
            return nil
        end
        local I = upvalues[5][1](E, v, b, h, R, w)
        local function n(Z)
            return I(math.min(Z, S - 1))
        end
        local C = ffi.new("int16_t[?]", U)
        local t = L / upvalues[3][1]
        for Z = 0, U - 1, 1 do
            local r = Z * t
            local E = math.floor(r)
            local V
            if t > 1 then
                local P = math.min((Z + 1) * t, S)
                local b = 0
                for Z = E, math.ceil(P) - 1, 1 do
                    b = b + n(Z) * (math.min(Z + 1, P) - math.max(Z, r))
                end
                V = b / (P - r)
            else
                local Z = r - E
                V = n(E) * (1 - Z) + n(E + 1) * Z
            end
            C[Z] = math.max(-32768, math.min(32767, math.floor(V * 32768 + 0.5)))
        end
        local N = U * 2
        local q = "RIFF" .. (upvalues[6][1](N + 36, 4) .. ("WAVEfmt " .. (upvalues[6][1](16, 4) .. (upvalues[6][1](1, 2) .. (upvalues[6][1](1, 2) .. (upvalues[6][1](upvalues[3][1], 4) .. (upvalues[6][1](upvalues[3][1] * 2, 4) .. (upvalues[6][1](2, 2) .. (upvalues[6][1](16, 2) .. ("data" .. upvalues[6][1](N, 4)))))))))))
        return q .. ffi.string(C, N), U / upvalues[3][1]
    end, environment)
end

