        registers[21] = "    var hud = $.GetContextPanel();\n    function insert_icon(notice, target_id, icon_path, icon_id, after) {\n        if (!icon_path || notice.FindChildTraverse(icon_id) !== null) return;\n\n        var target = notice.FindChildTraverse(target_id);\n        if (target === null || target.GetParent() === null) return;\n\n        var parent = target.GetParent();\n        var icon = $.CreatePanel('Image', parent, icon_id);\n        icon.SetImage(icon_path);\n        icon.style.width = '16px';\n        icon.style.height = '16px';\n        icon.style.marginLeft = after ? '3px' : '0px';\n        icon.style.marginRight = after ? '0px' : '3px';\n        icon.style.verticalAlign = 'center';\n        icon.style.imgShadow = '0px 0px 2px 1.0 #000000aa';\n\n        if (after) parent.MoveChildAfter(icon, target);\n        else parent.MoveChildBefore(icon, target);\n    }\n\n    function add_icons(attacker_name, victim_name, attacker_icon, victim_icon) {\n        var attempts = 0;\n\n        function apply() {\n            var feed = hud.FindChildTraverse('HudDeathNotice');\n            var notices = feed && feed.FindChildTraverse('VisibleNotices');\n            if (notices !== null && notices.GetChildCount() > 0) {\n                for (var i = notices.GetChildCount() - 1; i >= 0; i--) {\n                    var notice = notices.GetChild(i);\n                    var killer = notice.FindChildTraverse('DeathNotice_Killer');\n                    var victim = notice.FindChildTraverse('DeathNotice_Victim');\n                    var killer_matches = !attacker_icon || (killer !== null && killer.text === attacker_name);\n                    var victim_matches = !victim_icon || (victim !== null && victim.text === victim_name);\n\n                    if (killer_matches && victim_matches) {\n                        insert_icon(notice, 'DeathNotice_Killer', attacker_icon, 'RevealerKillerIcon', false);\n                        insert_icon(notice, 'DeathNotice_Victim', victim_icon, 'RevealerVictimIcon', true);\n                        return;\n                    }\n                }\n            }\n\n            if (++attempts < 6) $.Schedule(0.01, apply);\n        }\n\n        $.Schedule(0.0, apply);\n    }\n\n    function clear_icons() {\n        var feed = hud.FindChildTraverse('HudDeathNotice');\n        var notices = feed && feed.FindChildTraverse('VisibleNotices');\n        if (notices === null) return;\n\n        for (var i = 0; i < notices.GetChildCount(); i++) {\n            var notice = notices.GetChild(i);\n            var killer = notice.FindChildTraverse('RevealerKillerIcon');\n            var victim = notice.FindChildTraverse('RevealerVictimIcon');\n            if (killer !== null) killer.DeleteAsync(0.0);\n            if (victim !== null) victim.DeleteAsync(0.0);\n        }\n    }\n\n    return { add_icons: add_icons, clear_icons: clear_icons };\n"
